def floor_ceil(a: list[int], x: int) -> tuple[int | None, int | None]:
    lo, hi = 0, len(a) - 1
    floor = ceil = None
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if a[mid] == x:
            return a[mid], a[mid]
        if a[mid] < x:
            floor = a[mid]
            lo = mid + 1
        else:
            ceil = a[mid]
            hi = mid - 1
    return floor, ceil
